package com.ptms.service;import com.ptms.domain.PersonType;import org.springframework.stereotype.Service;import java.time.*;
@Service public class ParkingDurationService{private final SettingsService settings;public ParkingDurationService(SettingsService settings){this.settings=settings;}public int requiredTicketHours(PersonType type,boolean pass,LocalDate date,LocalTime entry,LocalTime exit,Integer extra){if(!exit.isAfter(entry))throw new IllegalArgumentException("Exit time must be later than entry time");var cfg=settings.get();long mins=Duration.between(entry,exit).toMinutes()+(extra==null?0:extra)*60L+cfg.bufferMinutes();if(type==PersonType.EMPLOYEE&&pass){boolean weekend=date.getDayOfWeek()==DayOfWeek.SATURDAY||date.getDayOfWeek()==DayOfWeek.SUNDAY;LocalTime ps=LocalTime.parse(weekend?cfg.weekendStart():cfg.weekdayStart()),pe=LocalTime.parse(weekend?cfg.weekendEnd():cfg.weekdayEnd());LocalTime s=entry.isAfter(ps)?entry:ps,e=exit.isBefore(pe)?exit:pe;if(e.isAfter(s))mins-=Duration.between(s,e).toMinutes();}return(int)Math.ceil(Math.max(0,mins)/60.0);}}
